'use strict';

// MODULES //

import hypot from '@stdlib/math-base-special-hypot';


// MAIN //

/**
* Evaluates the signum function of a double-precision complex floating-point number and assigns results to a provided output array.
*
* @param {number} re - real component
* @param {number} im - imaginary component
* @param {Collection} out - output array
* @param {integer} strideOut - stride length
* @param {NonNegativeInteger} offsetOut - starting index
* @returns {Collection} output array
*
* @example
* import Float64Array from '@stdlib/array-float64';
*
* var out = assign( 3.0, -4.0, new Float64Array( 2 ), 1, 0 );
* // returns <Float64Array>[ 0.6, -0.8 ]
*/
function assign( re, im, out, strideOut, offsetOut ) {
	var az;

	az = hypot( re, im );
	if ( az === 0.0 ) {
		out[ offsetOut ] = re;
		out[ offsetOut+strideOut ] = im;
		return out;
	}
	out[ offsetOut ] = re / az;
	out[ offsetOut+strideOut ] = im / az;
	return out;
}


// EXPORTS //

export default assign;
